def point(cx, cy, r, deg):
    a=math.radians(deg)
    return (cx+r*math.cos(a), cy+r*math.sin(a))

def sector_path(cx, cy, r0, r1, a0, a1):
    x1,y1=point(cx,cy,r1,a0); x2,y2=point(cx,cy,r1,a1)
    x3,y3=point(cx,cy,r0,a1); x4,y4=point(cx,cy,r0,a0)
    large=1 if abs(a1-a0)>180 else 0
    return f"M {x1:.1f} {y1:.1f} A {r1} {r1} 0 {large} 1 {x2:.1f} {y2:.1f} L {x3:.1f} {y3:.1f} A {r0} {r0} 0 {large} 0 {x4:.1f} {y4:.1f} Z"

cx,cy=120,390
sections=[]
def add_ring(labels,r0,r1,start,end,color,kind,our_pick=False):
    n=len(labels); step=(end-start)/n
    for i,label in enumerate(labels):
        a0=start+i*step+0.8
        a1=start+(i+1)*step-0.8
        am=(a0+a1)/2
        rm=(r0+r1)/2
        lx,ly=point(cx,cy,rm,am)
        if kind=="300":
            desc=f"Section {label} is in the 300 level — Vegas Sidekick’s Sweet Spot / Our Pick for The Wizard of Oz at Sphere. It sits in the middle band of the seating bowl for a strong overall read of the giant screen."
            badge="Sweet spot"
        elif kind=="200":
            desc=f"Section {label} is in the 200 level, closer to the screen. Pick this level when you want the screen to feel especially large in your field of view."
            badge="Closer view"
        else:
            desc=f"Section {label} is in the 400 level, higher in the bowl. It gives you a wider overall look at the Sphere screen and the full visual composition."
            badge="Wider view"
        sections.append({"id":str(label),"label":str(label),"level":kind,"path":sector_path(cx,cy,r0,r1,a0,a1),"label_x":round(lx,1),"label_y":round(ly,1),"color":color,"our_pick":bool(our_pick),"badge":badge,"description":desc})

add_ring([210,209,208,207,206,205,204,203,202],175,250,-70,70,"#ff2e7e","200")
add_ring([310,309,308,307,306,305,304,303,302],262,350,-70,70,"#8d3cff","300",True)
