js=r'''(()=>{const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));async function mount(root){const url=root.dataset.layoutUrl,ticket=root.dataset.ticketUrl;try{const data=await fetch(url,{credentials:'same-origin'}).then(r=>{if(!r.ok)throw new Error(`HTTP ${r.status}`);return r.json()});const byId=Object.fromEntries(data.sections.map(s=>[s.id,s]));const zone=s=>`<g class="sphere-map-zone${s.our_pick?' is-pick':''}" data-zone="${esc(s.id)}" role="button" tabindex="0" aria-label="Section ${esc(s.label)}${s.our_pick?', Sweet Spot / Our Pick':''}" style="--zone-color:${esc(s.color)}"><path d="${esc(s.path)}"></path><text x="${esc(s.label_x)}" y="${esc(s.label_y)}">${esc(s.label)}</text></g>`;const sc=data.screen;root.innerHTML=`<div><div class="sphere-map-shell"><svg viewBox="${esc(data.viewBox)}" role="img" aria-label="Sphere Las Vegas seating layout"><rect class="sphere-screen" x="${sc.x}" y="${sc.y}" width="${sc.width}" height="${sc.height}" rx="${sc.rx}"></rect><text class="sphere-screen-label" transform="translate(${sc.label_x} ${sc.label_y}) rotate(-90)">SCREEN</text>${data.sections.map(zone).join('')}${data.overhang_labels.map(o=>`<text class="sphere-overhang" x="${o.x}" y="${o.y}">${esc(o.text)}</text>`).join('')}</svg><div class="sphere-map-caption"><strong>${esc(data.venue)}</strong><span>${esc(data.address)}</span></div></div></div><div><div class="sphere-seat-detail" aria-live="polite"><span class="tag">Sweet spot</span><h3>Section 306</h3><p>${esc(byId[data.default_section].description)}</p><a class="cta vs-ticket-primary" href="${esc(ticket)}" target="_blank" rel="noopener sponsored">Check seats →</a></div><div class="sphere-legend"><span><i style="--legend-color:#ff2e7e"></i>200 level · closer to the screen</span><span><i style="--legend-color:#8d3cff"></i>300 level · Sweet Spot / Our Pick</span><span><i style="--legend-color:#12c7b1"></i>400 level · wider overall view</span></div></div><div class="sphere-mobile-popover" aria-live="polite" aria-atomic="true"><div><span class="sphere-mobile-badge">Sweet spot</span><strong>Section 306</strong><p>${esc(byId[data.default_section].description)}</p></div><button type="button" aria-label="Close seat description">×</button></div>`;const detail=root.querySelector('.sphere-seat-detail'),pop=root.querySelector('.sphere-mobile-popover');const badge=s=>s.our_pick?'Sweet spot':s.badge;const activate=(id,showPop=false)=>{const s=byId[id];if(!s)return;root.querySelectorAll('[data-zone]').forEach(el=>el.classList.toggle('is-active',el.dataset.zone===id));detail.querySelector('.tag').textContent=badge(s);detail.querySelector('h3').textContent=`Section ${s.label}`;detail.querySelector('p').textContent=s.description;pop.querySelector('.sphere-mobile-badge').textContent=badge(s);pop.querySelector('strong').textContent=`Section ${s.label}`;pop.querySelector('p').textContent=s.description;if(showPop&&matchMedia('(max-width:820px)').matches)pop.classList.add('is-open')};root.addEventListener('click',e=>{const z=e.target.closest('[data-zone]');if(z)activate(z.dataset.zone,true);if(e.target.closest('.sphere-mobile-popover>button'))pop.classList.remove('is-open')});root.addEventListener('keydown',e=>{const z=e.target.closest('[data-zone]');if(z&&(e.key==='Enter'||e.key===' ')){e.preventDefault();activate(z.dataset.zone,true)}});addEventListener('scroll',()=>pop.classList.remove('is-open'),{passive:true});activate(data.default_section)}catch(err){root.innerHTML='<p>Seat guide unavailable right now. Use the live ticket map to compare sections for your date.</p>';console.warn('Sphere seat guide:',err)}}function enhanceGallery(){const buttons=[...document.querySelectorAll('#photos .gallery button')],light=document.getElementById('lightbox');if(!buttons.length||!light)return;const img=light.querySelector('#lightboxImg, img');if(!img)return;let current=0,touchX=null,prev=light.querySelector('.sphere-lb-prev'),next=light.querySelector('.sphere-lb-next'),count=light.querySelector('.sphere-lb-count');if(!prev){prev=document.createElement('button');prev.type='button';prev.className='sphere-lb-nav sphere-lb-prev';prev.setAttribute('aria-label','Previous photo');prev.textContent='‹';light.appendChild(prev);next=document.createElement('button');next.type='button';next.className='sphere-lb-nav sphere-lb-next';next.setAttribute('aria-label','Next photo');next.textContent='›';light.appendChild(next);count=document.createElement('div');count.className='sphere-lb-count';light.appendChild(count)}const show=i=>{current=(i+buttons.length)%buttons.length;const thumb=buttons[current].querySelector('img');img.src=thumb.currentSrc||thumb.src;img.alt=thumb.alt||'The Wizard of Oz at Sphere photo';count.textContent=`${current+1} of ${buttons.length}`};buttons.forEach((b,i)=>b.addEventListener('click',()=>show(i)));prev.addEventListener('click',e=>{e.stopPropagation();show(current-1)});next.addEventListener('click',e=>{e.stopPropagation();show(current+1)});addEventListener('keydown',e=>{if(!light.classList.contains('open'))return;if(e.key==='ArrowLeft')show(current-1);if(e.key==='ArrowRight')show(current+1)});light.addEventListener('touchstart',e=>{touchX=e.changedTouches[0]?.clientX??null},{passive:true});light.addEventListener('touchend',e=>{if(touchX==null)return;const dx=(e.changedTouches[0]?.clientX??touchX)-touchX;touchX=null;if(Math.abs(dx)>45)show(current+(dx<0?1:-1))},{passive:true})}document.querySelectorAll('[data-seat-layout="sphere-las-vegas"]').forEach(mount);enhanceGallery()})();'''
(ROOT/"assets/seat-layouts/sphere-las-vegas.js").write_text(js+"\n",encoding="utf-8")

